  "prompt": "prompts/physics_committee_luna_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Jon Magne Leinaas",
        "Jan Myrheim",
        "Moty Heiblum"
      ],
      "assessment": {
        "nobel_worthiness": "Establishing fractional charge and anyonic exchange statistics reveals genuinely new quantum behavior and has reshaped understanding of two-dimensional matter.",
        "attribution": "Leinaas and Myrheim made an early foundational proposal for anyons; Heiblum led important experimental work on fractional charge and anyonic statistics. The broader fractional quantum Hall theory and experimental history involve major contributors beyond this credited set.",
        "maturity": "Fractional charge is well established, and evidence for anyonic statistics has advanced through increasingly direct interferometry experiments.",
        "uncertainties": [
          "The interpretation and robustness of some anyon-statistics measurements remain debated, and the credited names do not capture the full theoretical and experimental contributions."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B036",
      "proposed_laureates": [
        "Michael Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "The Aharonov-Bohm effect and Berry phase expose the physical role of quantum phase and have become powerful principles across physics.",
        "attribution": "Aharonov, with Bohm, established the magnetic-potential effect; Berry identified the geometric phase in adiabatic evolution. Both are central, distinct contributions.",
        "maturity": "Both effects have been confirmed in many systems and are now standard parts of quantum theory and experiment.",
        "uncertainties": [
          "The candidate combines two related but historically distinct discoveries, each with additional contributors and antecedents."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Alexander A. Belavin",
        "Alexander B. Zamolodchikov",
        "Alexander M. Polyakov"
      ],
      "assessment": {
        "nobel_worthiness": "Two-dimensional conformal field theory supplied exact tools for critical phenomena and influenced statistical mechanics, particle theory, and string theory.",
        "attribution": "Belavin, Polyakov, and Zamolodchikov's work was foundational in applying conformal symmetry to two-dimensional critical systems; the field also rests on a wider mathematical and physical lineage.",
        "maturity": "The framework and its consequences have been extensively tested against exact results and experiments on critical systems.",
        "uncertainties": [
          "The awardable contribution may be difficult to delimit from earlier conformal ideas and later work by a broad community."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Alan H. Guth",
        "Andrei Linde",
        "Viatcheslav Mukhanov"
      ],
      "assessment": {
        "nobel_worthiness": "Inflation offers a compelling account of the universe's large-scale uniformity and a physical origin for primordial structure.",
        "attribution": "Guth and Linde developed influential inflationary scenarios; Mukhanov made foundational contributions to the theory of primordial fluctuations. Many researchers developed the broader framework.",
        "maturity": "The predicted spectrum of fluctuations is consistent with precision cosmological observations, though inflation itself has not been uniquely established.",
        "uncertainties": [
          "No distinctive direct signature, such as primordial gravitational waves, has yet confirmed inflation, and competing models can explain much of the observed data."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B024",
      "proposed_laureates": [
        "Francis Halzen"
      ],
      "assessment": {
        "nobel_worthiness": "The discovery of high-energy astrophysical neutrinos opened a new observational window on the universe and established neutrinos as tools for studying extreme cosmic sources.",
        "attribution": "Halzen was a leading architect and scientific advocate of IceCube; the discovery depended on the work of a large international collaboration.",
        "maturity": "The astrophysical neutrino flux is supported by multiple analyses and years of data, with source populations increasingly constrained.",
        "uncertainties": [
          "The specific cosmic sources and acceleration mechanisms remain incompletely identified, and individual attribution is difficult for a collaboration-scale discovery."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B020",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Tilman Esslinger"
      ],
      "assessment": {
        "nobel_worthiness": "Optical-lattice experiments made controlled studies of quantum many-body phenomena possible and created a versatile setting for testing condensed-matter models.",
        "attribution": "Bloch, Greiner, and Esslinger led influential experimental demonstrations across distinct platforms; the theoretical proposals and wider experimental effort also deserve recognition.",
        "maturity": "The approach is established and has produced robust observations of quantum phases and dynamics, with continuing progress toward harder many-body regimes.",
        "uncertainties": [
          "The field's lasting conceptual discoveries are still accumulating, and the contribution spans several groups and theoretical work."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B031",
      "proposed_laureates": [
        "Juan Maldacena",
        "Edward Witten"
      ],
      "assessment": {
        "nobel_worthiness": "Gauge/gravity duality is a striking and influential connection between quantum field theory and gravity, with deep consequences for theoretical physics.",
        "attribution": "Maldacena formulated the best-known duality; Witten developed and clarified its implications. Polyakov's earlier contributions to string theory and related ideas complicate a narrow attribution.",
        "maturity": "The correspondence is mathematically powerful and has generated substantial work, but its physical realization in nature has not been established.",
        "uncertainties": [
          "The duality's empirical status is indirect, and its foundational significance may be judged differently from experimentally confirmed discoveries."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Bertrand I. Halperin",
        "David R. Nelson",
        "A. Peter Young"
      ],
      "assessment": {
        "nobel_worthiness": "The theory of defect-mediated melting and the hexatic phase gave a profound account of how order disappears in two dimensions.",
        "attribution": "Nelson and Halperin developed the central theory, with Young making major contributions to its analysis; the result rests on a connected body of work.",
        "maturity": "The predictions have been tested in diverse two-dimensional systems, and the framework remains influential in statistical physics.",
        "uncertainties": [
          "Some real systems depart from the idealized transitions, and the experimental realization of clean hexatic behavior depends on material and conditions."
        ]
      }
    }
  ]
}
